def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str.isdigit() or N <= 0 or K < 0 or K >= N:
        raise ValueError("Invalid input: num_str must be a digit string, N must be positive, and K must be non-negative and less than N.")

    def split_and_multiply(parts):
        product = 1
        for part in parts:
            product *= int(part)
        return product

    def backtrack(start, k, parts):
        if k == 0:
            parts.append(num_str[start:])
            max_prod = split_and_multiply(parts)
            parts.pop()
            return max_prod

        max_product = 0
        for i in range(start + 1, N - k + 2):
            parts.append(num_str[start:i])
            max_product = max(max_product, backtrack(i, k - 1, parts))
            parts.pop()

        return max_product

    return backtrack(0, K, [])

