def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        # Remove hyphens and convert to list of characters
        chars = list(isbn.replace('-', ''))
        total = 0
        for i in range(9):
            total += (i + 1) * int(chars[i])
        checksum = total % 11
        return 'X' if checksum == 10 else str(checksum)

    try:
        # Validate input format
        if len(isbn) != 13 or isbn[1] != '-' or isbn[5] != '-' or isbn[11] != '-':
            raise ValueError("Invalid ISBN format")

        # Calculate expected checksum
        expected_checksum = calculate_checksum(isbn)

        # Extract actual checksum
        actual_checksum = isbn[12]

        # Compare and return result
        if actual_checksum == expected_checksum:
            return "Right"
        else:
            # Correct the ISBN by replacing the last character with the expected checksum
            corrected_isbn = isbn[:12] + expected_checksum
            return corrected_isbn
    except ValueError as e:
        raise ValueError(f"Invalid ISBN: {e}")

def count_passing_ways(n: int, m: int) -> int:
    if n < 1 or m < 0:
        raise ValueError("Invalid input: n must be at least 1 and m must be non-negative.")
    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] will be the number of ways to reach student i in j passes
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1

    for passes in range(1, m + 1):
        for student in range(n):
            left_neighbor = (student - 1) % n
            right_neighbor = (student + 1) % n
            dp[student][passes] = dp[left_neighbor][passes - 1] + dp[right_neighbor][passes - 1]

    return dp[0][m]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if n < 0 or m < 0 or any(price < 0 or value < 0 for price, value in items):
        raise ValueError("Budget and item values must be non-negative.")

    # Initialize a DP array where dp[j] is the maximum importance value for budget j
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, value in items:
        # Update the DP array from right to left to avoid using the same item multiple times
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + value * price)

    return dp[n]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not isinstance(n, int) or n < 0:
        raise ValueError("The degree n must be a non-negative integer.")
    if not isinstance(coeffs, list) or len(coeffs) != n + 1:
        raise ValueError("Coefficients must be a list with length n+1.")

    terms = []
    for degree in range(n, -1, -1):
        coeff = coeffs[n - degree]
        if coeff == 0:
            continue

        term = ""
        if coeff < 0:
            term += "-"
        elif len(terms) > 0:
            term += "+"

        if abs(coeff) != 1 or degree == 0:
            term += str(abs(coeff))

        if degree > 1:
            term += f"x^{degree}"
        elif degree == 1:
            term += "x"

        terms.append(term)

    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) < len(original):
        return "Failed"

    try:
        decoded_message = ''.join(mapping[c] for c in message)
    except KeyError:
        return "Failed"

    return decoded_message

def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    # Start with the smallest prime number
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            # If i is a factor, then n // i is the other factor
            # Since n is the product of exactly two distinct primes, n // i is the larger one
            return n // i

    # If no factors are found, n itself is a prime number (though per the problem statement, this case shouldn't occur)
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    def helper(n, k, x):
        if k == 1:
            return 1 if n >= x else 0
        if n < k * x:
            return 0
        if k == n:
            return 1
        return helper(n - x, k - 1, x) + helper(n - 1, k, x + 1)

    try:
        if n < k * x or k <= 0 or x <= 0:
            return 0
        return helper(n, k, x)
    except RecursionError:
        return 0

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last < 1 or n < 1:
        return 0
    if last in memo:
        return memo[last]

    total_sequences = 1  # The sequence consisting of only the starting number 'n'
    for i in range(1, (last // 2) + 1):
        total_sequences += count_sequences(n, i, memo)

    memo[last] = total_sequences
    return total_sequences

def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 <= 0 or y0 <= 0 or y0 % x0 != 0:
        return 0

    from math import gcd

    count = 0
    target = y0 // x0

    for a in range(1, int(target**0.5) + 1):
        if target % a == 0:
            b = target // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

