def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Convert the number to a string for easy digit manipulation
    str_n = str(n)
    digits = set(str_n)

    # Create a transformation map from the rules
    transform_map = defaultdict(set)
    for x, y in rules:
        transform_map[str(x)].add(str(y))

    # BFS initialization
    queue = deque([str_n])
    visited = set([str_n])

    while queue:
        current = queue.popleft()

        # Generate all possible transformations of the current number
        for i in range(len(current)):
            if current[i] in transform_map:
                for new_digit in transform_map[current[i]]:
                    new_number = current[:i] + new_digit + current[i+1:]
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    try:
        for person, stmts in statements.items():
            for stmt in stmts:
                # Check if the statement is about the day of the week
                if any(day in stmt for day in days_of_week):
                    continue

                # Determine if the statement is a claim about guilt or innocence
                if "guilty" in stmt:
                    target, _, _ = stmt.partition(" is guilty.")
                    # If the statement is made by a liar, it should be false
                    if person in liar_count:
                        if target.strip().upper() == scenario:
                            return False
                    else:
                        if target.strip().upper() != scenario:
                            return False
                elif "not guilty" in stmt:
                    target, _, _ = stmt.partition(" is not guilty.")
                    # If the statement is made by a liar, it should be false
                    if person in liar_count:
                        if target.strip().upper() == scenario:
                            return False
                    else:
                        if target.strip().upper() == scenario:
                            return False
        return True
    except Exception as e:
