def calculate_score(system: int, points: str) -> list:
    if system not in [11, 21]:
        raise ValueError("The system must be either 11 or 21.")
    if not all(char in 'WL' for char in points):
        raise ValueError("The points string must only contain 'W' and 'L' characters.")

    game_scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        # Check if the game is finished
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # If the loop ends and there's an unfinished game, add it to the list
    if player_score > 0 or opponent_score > 0:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("The input must be a non-negative integer.")

    # Base case
    if n == 0:
        return 1

    # Create a list to store the catalan numbers up to n
    catalan = [0] * (n + 1)

    # Initialize the first catalan number
    catalan[0] = 1

    # Compute the catalan numbers up to n using the recursive formula
    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

