        cleared.update(range(start, end + 1))

    return l - len(cleared)

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V <= 0:
        return V
    if n <= 0 or not volumes:
        return V

    # Initialize the DP array where dp[i] will be True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # A subset with volume 0 is always possible (empty subset)

    for volume in volumes:
        # Traverse backwards to avoid using the same item multiple times
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be achieved which is less than or equal to V
    for max_volume in range(V, -1, -1):
        if dp[max_volume]:
            return V - max_volume

    return V  # If no items can be fit, return the full volume as remaining space

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # dp[i][j] will store the number of ways to arrange j pots using the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There is one way to arrange 0 pots (by choosing nothing)
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            # We can choose anywhere from 0 to a[i-1] pots of the ith type
            for k in range(min(j, a[i - 1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must consist only of alphabetic characters.")

    key = key.lower()
    ciphertext = ciphertext.lower()
    decrypted_text = []
    key_length = len(key)

    for i, char in enumerate(ciphertext):
        key_char = key[i % key_length]
        shift = ord(key_char) - ord('a')
        decrypted_char = chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
        decrypted_text.append(decrypted_char)

    return ''.join(decrypted_text)

def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    if a < 0 or b <= 0:
        raise ValueError("a must be non-negative and b must be positive")

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

